     * The owner's numeric membership level, mapped from the owner's membership points; null
     * when there is no owner.
     *
     * @see MembershipLevel
     */
    default Integer membershipLevel(Owner owner) {
        if (owner == null) {
            return null;
        }
        return MembershipLevel.of(owner);
    }

